export function partCostCents(quote,settle){if(!Number.isSafeInteger(quote)||!Number.isSafeInteger(settle)||quote<0||settle<0||quote>protocol.publicParts.Quote||settle>protocol.publicParts.Settle)throw Error('Invalid part quantity');return (quote+settle)*30;}
export function tierEstimate(tierId,freeStarter=false){const tier=tiers.find(t=>t.id===tierId);if(!tier)throw Error('Unknown rarity');const paidQuote=tier.quote-(freeStarter?4:0),paidSettle=tier.settle-(freeStarter?1:0);return {quote:tier.quote,settle:tier.settle,paidQuote,paidSettle,cents:partCostCents(paidQuote,paidSettle)};}
export function projectedReward(tierId,seconds=604800){const tier=tiers.find(t=>t.id===tierId);if(!tier||!Number.isInteger(seconds)||seconds<0||seconds>604800)throw Error('Invalid reward preview');return Number(tier.pool)*seconds/604800/tier.count;}
